read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'PanelFrame' -> merge_msg_PanelFrame(Prev, New, TrUserData);
        'PanelExec' -> merge_msg_PanelExec(Prev, New, TrUserData);
        'PanelExecResult' -> merge_msg_PanelExecResult(Prev, New, TrUserData);
        'PanelRequest' -> merge_msg_PanelRequest(Prev, New, TrUserData);
        'PanelResponse' -> merge_msg_PanelResponse(Prev, New, TrUserData);
        'PanelStream' -> merge_msg_PanelStream(Prev, New, TrUserData);
        'LlmChunk' -> merge_msg_LlmChunk(Prev, New, TrUserData);
        'JsonField' -> merge_msg_JsonField(Prev, New, TrUserData);
        'ToolParameter' -> merge_msg_ToolParameter(Prev, New, TrUserData);
        'ToolParameters' -> merge_msg_ToolParameters(Prev, New, TrUserData);
        'JsonObject' -> merge_msg_JsonObject(Prev, New, TrUserData);
        'JsonArray' -> merge_msg_JsonArray(Prev, New, TrUserData);
        'JsonValue' -> merge_msg_JsonValue(Prev, New, TrUserData);
        'ToolFunction' -> merge_msg_ToolFunction(Prev, New, TrUserData);
        'ToolCall' -> merge_msg_ToolCall(Prev, New, TrUserData);
        'ToolEvent' -> merge_msg_ToolEvent(Prev, New, TrUserData);
        'FinalAnswer' -> merge_msg_FinalAnswer(Prev, New, TrUserData);
        'StreamError' -> merge_msg_StreamError(Prev, New, TrUserData);
        'StartSessionArgs' -> merge_msg_StartSessionArgs(Prev, New, TrUserData);
        'SendArgs' -> merge_msg_SendArgs(Prev, New, TrUserData);
        'ApproveArgs' -> merge_msg_ApproveArgs(Prev, New, TrUserData);
        'BrainStatusArgs' -> merge_msg_BrainStatusArgs(Prev, New, TrUserData);
        'GetHistoryArgs' -> merge_msg_GetHistoryArgs(Prev, New, TrUserData);
        'DeleteSessionArgs' -> merge_msg_DeleteSessionArgs(Prev, New, TrUserData);
        'StartSessionResult' -> merge_msg_StartSessionResult(Prev, New, TrUserData);
        'SendResult' -> merge_msg_SendResult(Prev, New, TrUserData);
        'ListToolsResult' -> merge_msg_ListToolsResult(Prev, New, TrUserData);
        'ToolDesc' -> merge_msg_ToolDesc(Prev, New, TrUserData);
        'ListCapabilitiesResult' -> merge_msg_ListCapabilitiesResult(Prev, New, TrUserData);
        'CapabilityDesc' -> merge_msg_CapabilityDesc(Prev, New, TrUserData);
        'DebugCapabilityArgs' -> merge_msg_DebugCapabilityArgs(Prev, New, TrUserData);
        'DebugCapabilityResult' -> merge_msg_DebugCapabilityResult(Prev, New, TrUserData);
        'ApproveResult' -> merge_msg_ApproveResult(Prev, New, TrUserData);
        'BrainStatusResult' -> merge_msg_BrainStatusResult(Prev, New, TrUserData);
        'HistoryEntry' -> merge_msg_HistoryEntry(Prev, New, TrUserData);
        'GetHistoryResult' -> merge_msg_GetHistoryResult(Prev, New, TrUserData);
        'StopResult' -> merge_msg_StopResult(Prev, New, TrUserData);
        'DeleteSessionResult' -> merge_msg_DeleteSessionResult(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,merge_msg_PanelFrame/3}).
merge_msg_PanelFrame(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{request := PFrequest}, #{request := NFrequest}} -> S1#{request => merge_msg_PanelRequest(PFrequest, NFrequest, TrUserData)};
        {#{response := PFresponse}, #{response := NFresponse}} -> S1#{response => merge_msg_PanelResponse(PFresponse, NFresponse, TrUserData)};
        {#{stream := PFstream}, #{stream := NFstream}} -> S1#{stream => merge_msg_PanelStream(PFstream, NFstream, TrUserData)};
        {#{exec := PFexec}, #{exec := NFexec}} -> S1#{exec => merge_msg_PanelExec(PFexec, NFexec, TrUserData)};
        {#{exec_result := PFexec_result}, #{exec_result := NFexec_result}} -> S1#{exec_result => merge_msg_PanelExecResult(PFexec_result, NFexec_result, TrUserData)};
        {_, #{request := NFrequest}} -> S1#{request => NFrequest};
        {_, #{response := NFresponse}} -> S1#{response => NFresponse};
        {_, #{stream := NFstream}} -> S1#{stream => NFstream};
        {_, #{exec := NFexec}} -> S1#{exec => NFexec};
        {_, #{exec_result := NFexec_result}} -> S1#{exec_result => NFexec_result};
        {#{request := PFrequest}, _} -> S1#{request => PFrequest};
        {#{response := PFresponse}, _} -> S1#{response => PFresponse};
        {#{stream := PFstream}, _} -> S1#{stream => PFstream};
        {#{exec := PFexec}, _} -> S1#{exec => PFexec};
        {#{exec_result := PFexec_result}, _} -> S1#{exec_result => PFexec_result};
        _ -> S1
    end.

-compile({nowarn_unused_function,merge_msg_PanelExec/3}).
merge_msg_PanelExec(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {_, #{agent_request := NFagent_request}} -> S2#{agent_request => NFagent_request};
        {#{agent_request := PFagent_request}, _} -> S2#{agent_request => PFagent_request};
        _ -> S2
    end.

-compile({nowarn_unused_function,merge_msg_PanelExecResult/3}).
merge_msg_PanelExecResult(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{agent_response := NFagent_response}} -> S2#{agent_response => NFagent_response};
             {#{agent_response := PFagent_response}, _} -> S2#{agent_response => PFagent_response};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{error := NFerror}} -> S3#{error => NFerror};
             {#{error := PFerror}, _} -> S3#{error => PFerror};
             _ -> S3
         end,
    case {PMsg, NMsg} of
        {_, #{terminal := NFterminal}} -> S4#{terminal => NFterminal};
        {#{terminal := PFterminal}, _} -> S4#{terminal => PFterminal};
        _ -> S4
    end.

-compile({nowarn_unused_function,merge_msg_PanelRequest/3}).
merge_msg_PanelRequest(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{method := NFmethod}} -> S2#{method => NFmethod};
             {#{method := PFmethod}, _} -> S2#{method => PFmethod};
             _ -> S2
         end,
    case {PMsg, NMsg} of
        {_, #{args_bytes := NFargs_bytes}} -> S3#{args_bytes => NFargs_bytes};
        {#{args_bytes := PFargs_bytes}, _} -> S3#{args_bytes => PFargs_bytes};
        _ -> S3
    end.

-compile({nowarn_unused_function,merge_msg_PanelResponse/3}).
merge_msg_PanelResponse(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {_, #{result_bytes := NFresult_bytes}} -> S2#{result_bytes => NFresult_bytes};
        {_, #{error := NFerror}} -> S2#{error => NFerror};
        {#{result_bytes := PFresult_bytes}, _} -> S2#{result_bytes => PFresult_bytes};
        {#{error := PFerror}, _} -> S2#{error => PFerror};
        _ -> S2
    end.

-compile({nowarn_unused_function,merge_msg_PanelStream/3}).
merge_msg_PanelStream(PMsg, NMsg, TrUserData) ->
